import { isValidElement, useState, type ReactNode } from "react";
import { SkipLink } from "../../components/SkipLink/SkipLink";
import { SidebarNav, type NavGroupData } from "../../components/SidebarNav/SidebarNav";
import { NotesStrip } from "../../components/NotesStrip/NotesStrip";
import { CreditsMeter } from "../../components/CreditsMeter/CreditsMeter";
import { Sidebar } from "./Sidebar";
import { Topbar } from "./Topbar";
import type {
  AppShellAccount,
  AppShellBreadcrumb,
  AppShellCredits,
  AppShellNotes,
  AppShellSearch,
  AppShellVariant,
} from "./types";
import "./AppShell.css";

export type {
  AppShellAccount,
  AppShellBreadcrumb,
  AppShellCredits,
  AppShellNotes,
  AppShellSearch,
  AppShellVariant,
} from "./types";

export interface AppShellProps {
  variant?: AppShellVariant;
  brandName?: string;
  brandMark?: ReactNode;
  /** Decorative caret by default (Booking). Pass `null` to hide. Not an app switcher. */
  brandAction?: ReactNode | null;
  skipHref?: string;
  skipLabel?: string;
  nav?: ReactNode;
  navGroups?: NavGroupData[];
  notes?: ReactNode | AppShellNotes;
  sidebarFooter?: ReactNode;
  credits?: AppShellCredits;
  leading?: ReactNode;
  breadcrumbs?: AppShellBreadcrumb[];
  crumbs?: ReactNode;
  onBack?: () => void;
  backLabel?: string;
  search?: ReactNode | AppShellSearch;
  actions?: ReactNode;
  account?: AppShellAccount;
  onSettings?: () => void;
  onHelp?: () => void;
  onCallLogs?: () => void;
  onNotifications?: () => void;
  notificationsAlert?: boolean;
  children: ReactNode;
  /** @deprecated Use `variant="list"`. Hides notes; hides BackButton. */
  listMode?: boolean;
  defaultCollapsed?: boolean;
  collapsed?: boolean;
  onCollapsedChange?: (collapsed: boolean) => void;
}

function isElementLike(value: unknown): boolean {
  return isValidElement(value) || Array.isArray(value) || typeof value === "string";
}

function isNotesConfig(value: AppShellProps["notes"]): value is AppShellNotes {
  return !!value && typeof value === "object" && !isElementLike(value) && "label" in value;
}

export function AppShell({
  variant,
  brandName = "paryatech",
  brandMark,
  brandAction,
  skipHref = "#main",
  skipLabel = "Skip to main content",
  nav,
  navGroups,
  notes,
  sidebarFooter,
  credits,
  leading,
  breadcrumbs,
  crumbs,
  onBack,
  backLabel,
  search,
  actions,
  account,
  onSettings,
  onHelp,
  onCallLogs,
  onNotifications,
  notificationsAlert = false,
  children,
  listMode,
  defaultCollapsed = false,
  collapsed: collapsedProp,
  onCollapsedChange,
}: AppShellProps) {
  const resolvedVariant: AppShellVariant = variant ?? (listMode ? "list" : "detail");
  const isList = resolvedVariant === "list";
  const [uncontrolled, setUncontrolled] = useState(defaultCollapsed);
  const collapsed = collapsedProp ?? uncontrolled;
  const setCollapsed = (next: boolean) => {
    onCollapsedChange?.(next);
    if (collapsedProp === undefined) setUncontrolled(next);
  };

  const navContent = navGroups ? <SidebarNav groups={navGroups} /> : nav;

  const notesNode = isNotesConfig(notes) ? (
    <NotesStrip
      label={notes.label}
      badge={notes.badge}
      onOpen={notes.onOpen}
      onAdd={notes.onAdd}
      tip={notes.tip}
      addTip={notes.addTip}
    />
  ) : (
    notes
  );

  const footerNode = sidebarFooter ?? (credits ? <CreditsMeter {...credits} /> : null);

  return (
    <div
      className={`pt-frame ${collapsed ? "pt-frame--collapsed" : ""} ${isList ? "pt-frame--list" : ""}`}
      data-shell-variant={resolvedVariant}
    >
      <SkipLink href={skipHref}>{skipLabel}</SkipLink>

      <Sidebar
        brandName={brandName}
        brandMark={brandMark}
        brandAction={brandAction}
        notes={notesNode}
        listMode={isList}
        footer={footerNode}
        collapsed={collapsed}
        onToggleCollapsed={() => setCollapsed(!collapsed)}
      >
        {navContent}
      </Sidebar>

      <main className="pt-workspace">
        <Topbar
          showBack={!isList}
          onBack={onBack}
          backLabel={backLabel ?? "Back"}
          leading={leading}
          breadcrumbs={breadcrumbs}
          crumbs={crumbs}
          search={search ?? { placeholder: "Search anything" }}
          actions={actions}
          account={account}
          onSettings={onSettings}
          onHelp={onHelp}
          onCallLogs={onCallLogs}
          onNotifications={onNotifications}
          notificationsAlert={notificationsAlert}
        />
        <div className="pt-scroll">
          <div className="pt-content" id="main">
            {children}
          </div>
        </div>
      </main>
    </div>
  );
}

export default AppShell;

import type { ReactNode } from "react";
import { Icon } from "../../icons";

export interface SidebarProps {
  brandName?: string;
  brandMark?: ReactNode;
  /** Defaults to Booking’s decorative caret. Pass `null` to hide. Not an app switcher. */
  brandAction?: ReactNode | null;
  notes?: ReactNode;
  listMode?: boolean;
  children?: ReactNode;
  footer?: ReactNode;
  collapsed?: boolean;
  onToggleCollapsed?: () => void;
}

const defaultMark = (
  <svg width="17" height="17" viewBox="0 0 32 32" fill="none" aria-hidden="true">
    <path
      d="M4 8.5C4 6.6 5.6 5 7.5 5h13.8c4.2 0 7.6 3.4 7.6 7.6 0 4.2-3.4 7.6-7.6 7.6h-6.1l-8 6.4c-1.4 1.1-3.2.1-3.2-1.6V8.5Z"
      fill="var(--on-brand)"
    />
    <path d="M11 12.4h9.4" stroke="var(--accent)" strokeWidth="2.4" strokeLinecap="round" />
  </svg>
);

const defaultCaret = <Icon name="chevronDown" size={15} />;

export function Sidebar({
  brandName = "paryatech",
  brandMark,
  brandAction,
  notes,
  listMode = false,
  children,
  footer,
  collapsed = false,
  onToggleCollapsed,
}: SidebarProps) {
  const caret = brandAction === undefined ? defaultCaret : brandAction;

  return (
    <aside className="pt-side" aria-label="Sidebar">
      <div className="pt-side__top">
        <span className="pt-brand-mark">{brandMark ?? defaultMark}</span>
        <span className="pt-brand-name">{brandName}</span>
        {caret ? <span className="pt-brand-action">{caret}</span> : null}
      </div>

      {!listMode && notes ? <div className="pt-side__notes">{notes}</div> : null}

      <div className="pt-side__scroll">{children}</div>

      <div className="pt-side__foot">
        {footer}
        <button
          type="button"
          className="pt-side-collapse"
          data-tip={collapsed ? "Expand sidebar" : "Collapse sidebar"}
          aria-expanded={!collapsed}
          aria-label={collapsed ? "Expand sidebar" : "Collapse sidebar"}
          onClick={() => onToggleCollapsed?.()}
        >
          <Icon name="collapse" size={16} />
          <span className="pt-side-collapse__txt">Collapse</span>
        </button>
      </div>
    </aside>
  );
}

export function SidebarFooter({
  children,
  className = "",
}: {
  children: ReactNode;
  className?: string;
}) {
  return <div className={`pt-sidebar-footer ${className}`.trim()}>{children}</div>;
}

export default Sidebar;

import type { ReactNode } from "react";
import { isValidElement } from "react";
import { BackButton } from "../../components/BackButton/BackButton";
import { Breadcrumbs, type BreadcrumbItem } from "../../components/Breadcrumbs/Breadcrumbs";
import { AccountMenu, type AccountMenuProps } from "../../components/AccountMenu/AccountMenu";
import { TopbarActions } from "../../components/TopbarActions/TopbarActions";
import { SearchField } from "../../components/SearchField/SearchField";
import type { AppShellAccount, AppShellSearch } from "./types";

export interface TopbarProps {
  showBack?: boolean;
  onBack?: () => void;
  backLabel?: string;
  leading?: ReactNode;
  breadcrumbs?: BreadcrumbItem[];
  crumbs?: ReactNode;
  search?: ReactNode | AppShellSearch;
  actions?: ReactNode;
  account?: AppShellAccount;
  onSettings?: () => void;
  onHelp?: () => void;
  onCallLogs?: () => void;
  onNotifications?: () => void;
  notificationsAlert?: boolean;
}

function isSearchConfig(value: TopbarProps["search"]): value is AppShellSearch {
  return !!value && typeof value === "object" && !isValidElement(value) && !Array.isArray(value);
}

export function Topbar({
  showBack = false,
  onBack,
  backLabel = "Back",
  leading,
  breadcrumbs,
  crumbs,
  search,
  actions,
  account,
  onSettings,
  onHelp,
  onCallLogs,
  onNotifications,
  notificationsAlert = false,
}: TopbarProps) {
  const searchNode = isSearchConfig(search) ? (
    <SearchField
      placeholder={search.placeholder ?? "Search anything"}
      aria-label={search["aria-label"] ?? "Search the workspace"}
      value={search.value}
      defaultValue={search.defaultValue}
      onChange={search.onChange}
    />
  ) : (
    search
  );

  const crumbNode = breadcrumbs ? (
    <Breadcrumbs items={breadcrumbs} />
  ) : crumbs ? (
    <nav className="pt-crumbs" aria-label="Breadcrumb">
      {crumbs}
    </nav>
  ) : null;

  const actionCluster = actions ?? (
    <TopbarActions
      onSettings={onSettings}
      onHelp={onHelp}
      onCallLogs={onCallLogs}
      onNotifications={onNotifications}
      notificationsAlert={notificationsAlert}
    />
  );

  const accountNode = account ? (
    <AccountMenu
      name={account.name}
      initials={account.initials}
      tone={account.tone}
      onClick={account.onClick}
    />
  ) : null;

  return (
    <div className="pt-topbar">
      {leading ?? (showBack ? <BackButton label={backLabel} onClick={onBack} /> : null)}
      {crumbNode}
      {searchNode}
      <div className="pt-topbar__actions">
        {actionCluster}
        {accountNode}
      </div>
    </div>
  );
}

export type { AccountMenuProps };

export default Topbar;

import type { ChangeEvent, ReactNode } from "react";
import type { AvatarTone } from "../../components/Avatar/Avatar";
import type { BreadcrumbItem } from "../../components/Breadcrumbs/Breadcrumbs";
import type { NotesStripProps } from "../../components/NotesStrip/NotesStrip";
import type { CreditsMeterProps } from "../../components/CreditsMeter/CreditsMeter";

export type AppShellVariant = "list" | "detail";

export interface AppShellSearch {
  placeholder?: string;
  value?: string;
  defaultValue?: string;
  onChange?: (event: ChangeEvent<HTMLInputElement>) => void;
  "aria-label"?: string;
}

export interface AppShellAccount {
  name: string;
  initials: string;
  tone?: AvatarTone;
  onClick?: () => void;
}

export type AppShellNotes = Pick<NotesStripProps, "label" | "badge" | "onOpen" | "onAdd" | "tip" | "addTip">;

export type AppShellCredits = Pick<CreditsMeterProps, "remaining" | "total" | "onUpgrade" | "tip">;

export type AppShellBreadcrumb = BreadcrumbItem;

.pt-frame {
  display: grid;
  grid-template-columns: 250px minmax(0, 1fr);
  gap: 10px;
  height: 100vh;
  width: 100%;
  max-width: 100%;
  padding: 10px;
  background: var(--ground);
  transition: grid-template-columns var(--duration-shell) cubic-bezier(0.4, 0, 0.2, 1);
}

.pt-frame--collapsed {
  grid-template-columns: 66px minmax(0, 1fr);
}

.pt-side {
  display: flex;
  flex-direction: column;
  min-height: 0;
  background: var(--side);
  border: 1px solid var(--line);
  border-radius: var(--radius-lg);
  box-shadow: var(--panelShadow);
  overflow: hidden;
}

.pt-side__top {
  display: flex;
  align-items: center;
  gap: 10px;
  padding: 16px 16px 12px;
}

.pt-brand-mark {
  width: 28px;
  height: 28px;
  border-radius: var(--radius-sm);
  background: var(--accent);
  display: grid;
  place-items: center;
  flex: none;
}

.pt-brand-name {
  font-family: var(--type-heading-brand-family);
  font-weight: var(--type-heading-brand-weight);
  font-size: var(--type-heading-brand-size);
  letter-spacing: var(--type-heading-brand-tracking);
  color: var(--ink);
}

.pt-brand-action {
  margin-left: auto;
  color: var(--ink-2);
  display: inline-flex;
  align-items: center;
  flex: none;
}

.pt-frame--collapsed .pt-brand-name,
.pt-frame--collapsed .pt-brand-action,
.pt-frame--collapsed .pt-side-collapse__txt {
  display: none;
}

.pt-frame--collapsed .pt-side__top {
  justify-content: center;
  padding: 16px 0 12px;
}

.pt-frame--collapsed .pt-side__scroll {
  padding: 6px 8px 12px;
}

.pt-frame--collapsed .pt-side__foot {
  padding: 8px;
}

.pt-side__notes {
  margin: 0;
}

.pt-frame--list .pt-side__notes {
  display: none;
}

.pt-side__scroll {
  flex: 1;
  min-height: 0;
  overflow-y: auto;
  padding: 6px 10px 12px;
}

.pt-side__foot {
  padding: 12px;
  border-top: 1px solid var(--line);
}

.pt-side-collapse {
  display: flex;
  align-items: center;
  gap: 10px;
  width: 100%;
  height: 34px;
  padding: 0 11px;
  margin-top: 12px;
  border: 1px solid var(--line);
  border-radius: var(--radius-sm);
  background: transparent;
  color: var(--ink-2);
  font-family: var(--type-label-compact-family);
  font-size: var(--type-label-compact-size);
  font-weight: var(--type-label-compact-weight);
  cursor: pointer;
  position: relative;
}

.pt-side-collapse:hover {
  background: var(--side-hover);
  color: var(--ink);
}

.pt-side-collapse svg {
  flex: none;
  transition: transform var(--duration-shell) cubic-bezier(0.4, 0, 0.2, 1);
}

.pt-frame--collapsed .pt-side-collapse {
  justify-content: center;
  padding: 0;
  margin-top: 12px;
}

.pt-frame--collapsed .pt-side-collapse svg {
  transform: rotate(180deg);
}

.pt-side-collapse[data-tip]::after {
  content: attr(data-tip);
  position: absolute;
  left: calc(100% + 12px);
  top: 50%;
  transform: translateY(-50%);
  padding: 6px 10px;
  border-radius: var(--radius-sm);
  background: var(--tooltip-ink);
  color: var(--on-brand, #fff);
  font-family: var(--type-label-tooltip-family);
  font-size: var(--type-label-tooltip-size);
  font-weight: var(--type-label-tooltip-weight);
  white-space: nowrap;
  opacity: 0;
  pointer-events: none;
  display: none;
  z-index: 400;
  box-shadow: var(--tooltipShadow);
}

.pt-frame--collapsed .pt-side-collapse[data-tip]:hover::after {
  display: block;
  opacity: 1;
}

.pt-workspace {
  border-radius: var(--radius-lg);
  background: var(--panel-ground);
  border: 1px solid var(--line);
  overflow: hidden;
  display: flex;
  flex-direction: column;
  min-width: 0;
  min-height: 0;
  box-shadow: var(--panelShadow);
  container-type: inline-size;
  container-name: shell;
}

.pt-topbar {
  display: flex;
  align-items: center;
  gap: 10px;
  padding: 10px 16px;
  border-bottom: 1px solid var(--line);
  background: var(--surface);
  flex: none;
  min-width: 0;
}

.pt-topbar .pt-search,
.pt-topbar .pt-search--full {
  flex: 0 1 340px;
  max-width: 380px;
}

.pt-topbar__actions {
  display: flex;
  align-items: center;
  gap: 10px;
  margin-left: auto;
  flex: none;
}

.pt-scroll {
  flex: 1;
  min-height: 0;
  min-width: 0;
  overflow-y: auto;
  overflow-x: hidden;
  background: var(--panel-ground);
  display: flex;
  flex-direction: column;
}

.pt-content {
  --page-pad: clamp(16px, 2.2cqi, 52px);
  width: 100%;
  max-width: 2000px;
  min-width: 0;
  margin: 0 auto;
  flex: 1 0 auto;
  display: flex;
  flex-direction: column;
  min-height: 100%;
  padding: 16px var(--page-pad) 0;
}

@media (min-width: 1440px) {
  .pt-frame {
    padding: 12px;
    gap: 12px;
  }
}

@media (min-width: 1920px) {
  .pt-frame {
    padding: 14px;
    gap: 14px;
  }
}

/* Matches --bp-shell (1000px); media queries cannot use custom props reliably */
@media (max-width: 1000px) {
  .pt-frame {
    grid-template-columns: 1fr;
    height: auto;
    min-height: 100vh;
    padding: 0;
    gap: 0;
    overflow: hidden;
  }
  .pt-side {
    display: none;
  }
  .pt-workspace {
    border-radius: 0;
    border: none;
    box-shadow: none;
    height: 100vh;
  }
}

@media (max-width: 900px) {
  .pt-topbar {
    padding: 8px 10px;
    gap: 6px;
    flex-wrap: wrap;
  }
  .pt-topbar .pt-search,
  .pt-topbar .pt-search--full {
    max-width: none;
    flex: 1 1 180px;
  }
}

@container shell (max-width: 900px) {
  .pt-topbar {
    padding: 8px 10px;
    gap: 6px;
    flex-wrap: wrap;
  }
  .pt-topbar .pt-search,
  .pt-topbar .pt-search--full {
    max-width: none;
    flex: 1 1 180px;
  }
}

@media (prefers-reduced-motion: reduce) {
  .pt-frame {
    transition: none;
  }
  .pt-side-collapse svg {
    transition: none;
  }
}
